// ── Regex ↔ DFA equivalence demo ───────────────────────────────
// The JS regex engine compiles each pattern to an internal NFA/DFA.
// We test both ways: regex API and hand-rolled DFA.

// Pattern: one or more digits followed by '.' followed by one or more digits
const decimalRegex = /^\d+\.\d+$/;

// Hand-rolled DFA for the same language
// States: 0=start, 1=integer-digits, 2=dot, 3=frac-digits(accept)
function isDecimal(s) {
  let state = 0;
  for (const ch of s) {
    if (state === 0) {
      state = /\d/.test(ch) ? 1 : -1;
    } else if (state === 1) {
      if (/\d/.test(ch))     state = 1;
      else if (ch === '.')   state = 2;
      else                   state = -1;
    } else if (state === 2) {
      state = /\d/.test(ch) ? 3 : -1;
    } else if (state === 3) {
      state = /\d/.test(ch) ? 3 : -1;
    } else {
      state = -1; // dead state
    }
  }
  return state === 3;
}

const tests = ['3.14', '0.5', '42.0', '3.', '.14', 'abc', '1.2.3'];
for (const t of tests) {
  const rx  = decimalRegex.test(t);
  const dfa = isDecimal(t);
  console.log(`'${t}': regex=${rx} dfa=${dfa} match=${rx === dfa}`);
}
// Both agree on every case — same language, two representations.

// ── Pumping lemma: why {a^n b^n} is not regular ─────────────────
// Suppose it were regular with pumping length p.
// Take s = a^p b^p.  Any split xyz with |xy| <= p means y = a^k (k>=1).
// Pumping: xy^2 z = a^(p+k) b^p — not equal counts => not in language. QED.
function isEqualAB(s) {
  return /^(a*)\1$/.test(s); // backreference — not a DFA!
  // ^ This requires a backreference: proof that the language needs more than regex.
}

// Correct check needs counting — impossible in a pure DFA
function isEqualABCorrect(s) {
  const match = s.match(/^(a+)(b+)$/);
  if (!match) return false;
  return match[1].length === match[2].length; // counting = non-regular feature
}

console.log(isEqualABCorrect('aaabbb')); // true
console.log(isEqualABCorrect('aabb'));   // true
console.log(isEqualABCorrect('aab'));    // false

// ── What regex CAN do (regular patterns) ────────────────────────
const examples = [
  { pattern: /^[A-Z][a-z]+$/,      desc: 'Capitalised word'          },
  { pattern: /^\d{3}-\d{2}-\d{4}$/, desc: 'SSN format'               },
  { pattern: /^(https?:\/\/)/,      desc: 'URL starts with http(s)://' },
  { pattern: /^[01]+$/,             desc: 'Binary string'              },
];

// ── What regex CANNOT do (non-regular) ──────────────────────────
// 1. Balanced brackets: ((())) — requires counting nesting depth
//    → Use a parser / pushdown automaton instead.
// 2. Palindromes: 'racecar', 'aba' — requires remembering the first half
//    → No finite automaton suffices.
// 3. Equal counts: a^n b^n — proved non-regular by pumping lemma above.
// 4. Repeated substrings with backreferences: (\w+)\1
//    → PCRE adds this but it makes the language non-regular and potentially slow.

// ── Catastrophic backtracking example ───────────────────────────
// Pattern: (a+)+  on input 'aaaa...ab'
// Each 'a' can be split between inner/outer + in exponentially many ways.
// Safe equivalent: /a+/  (linear, no catastrophic backtracking)

// Rule of thumb: avoid nested quantifiers (x+)+ and alternation inside *
// RE2 / Rust regex ban backreferences entirely, guaranteeing O(n) time.
console.log('Regular: fixed, finite memory patterns only.');
console.log('Non-regular: anything requiring unbounded counting or back-reference.');
